pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 _val) public {
        _val = bound(_val, 0, type(uint128).max);
        c.SetMinSum(_val);
        uint256 minSumAfter = c.MinSum();
        assertTrue(minSumAfter == _val);
    }
}
